param([string]$FrameDirectory=$PSScriptRoot,[string]$CandidatePath=(Join-Path $PSScriptRoot 'wolf_walk_n_candidate.png'))
$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Drawing;Add-Type -AssemblyName System.Security
$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$sourcePath=Join-Path $root 'Assets\Sprites\Animals\Wolf\wolf_walk.png';$targetRow=4
function Get-RectHash([System.Drawing.Bitmap]$Bitmap,[System.Drawing.Rectangle]$Rect){$clone=$Bitmap.Clone($Rect,[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);try{$d=$clone.LockBits([System.Drawing.Rectangle]::new(0,0,$clone.Width,$clone.Height),[System.Drawing.Imaging.ImageLockMode]::ReadOnly,[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);try{$length=[Math]::Abs($d.Stride)*$clone.Height;$bytes=[byte[]]::new($length);[System.Runtime.InteropServices.Marshal]::Copy($d.Scan0,$bytes,0,$length)}finally{$clone.UnlockBits($d)};$sha=[System.Security.Cryptography.SHA256]::Create();try{return [Convert]::ToHexString($sha.ComputeHash($bytes))}finally{$sha.Dispose()}}finally{$clone.Dispose()}}
function Copy-Cell([System.Drawing.Bitmap]$Source,[System.Drawing.Bitmap]$Destination,[int]$X,[int]$Y){$sd=$Source.LockBits([System.Drawing.Rectangle]::new(0,0,256,256),[System.Drawing.Imaging.ImageLockMode]::ReadOnly,[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);try{$dd=$Destination.LockBits([System.Drawing.Rectangle]::new($X,$Y,256,256),[System.Drawing.Imaging.ImageLockMode]::WriteOnly,[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);try{$buf=[byte[]]::new(1024);for($r=0;$r -lt 256;$r++){[System.Runtime.InteropServices.Marshal]::Copy([IntPtr]::Add($sd.Scan0,$r*$sd.Stride),$buf,0,1024);[System.Runtime.InteropServices.Marshal]::Copy($buf,0,[IntPtr]::Add($dd.Scan0,$r*$dd.Stride),1024)}}finally{$Destination.UnlockBits($dd)}}finally{$Source.UnlockBits($sd)}}
$loaded=[System.Drawing.Bitmap]::new($sourcePath);try{if($loaded.Width -ne 1536 -or $loaded.Height -ne 2048){throw 'Unexpected sheet size'};$candidate=$loaded.Clone([System.Drawing.Rectangle]::new(0,0,$loaded.Width,$loaded.Height),[System.Drawing.Imaging.PixelFormat]::Format32bppArgb)}finally{$loaded.Dispose()}
try{for($f=0;$f -lt 6;$f++){$sprite=[System.Drawing.Bitmap]::new((Join-Path $FrameDirectory ('sequence_N_final_v5_{0}.png' -f $f)));try{Copy-Cell $sprite $candidate ($f*256) ($targetRow*256)}finally{$sprite.Dispose()}};$candidate.Save($CandidatePath,[System.Drawing.Imaging.ImageFormat]::Png)}finally{$candidate.Dispose()}
$before=[System.Drawing.Bitmap]::new($sourcePath);$after=[System.Drawing.Bitmap]::new($CandidatePath);try{for($row=0;$row -lt 8;$row++){$rect=[System.Drawing.Rectangle]::new(0,$row*256,1536,256);$a=Get-RectHash $before $rect;$b=Get-RectHash $after $rect;if($row -eq $targetRow){if($a -eq $b){throw 'N row did not change'};Write-Output "row$row N changed (expected)"}else{if($a -ne $b){throw "Unexpected change row$row"};Write-Output "row$row unchanged"}};for($f=0;$f -lt 6;$f++){$cell=Get-RectHash $after ([System.Drawing.Rectangle]::new($f*256,$targetRow*256,256,256));$s=[System.Drawing.Bitmap]::new((Join-Path $FrameDirectory ('sequence_N_final_v5_{0}.png' -f $f)));try{$source=Get-RectHash $s ([System.Drawing.Rectangle]::new(0,0,256,256))}finally{$s.Dispose()};if($cell -ne $source){throw "N frame$f differs"};Write-Output "N frame$f exact"}}finally{$before.Dispose();$after.Dispose()};Get-Item $CandidatePath|Select-Object FullName,Length,LastWriteTime
